<?php
require __DIR__.'/bootstrap.php';
$id=(int)($_GET['id']??$_POST['contract_id']??0);$c=$contractManager->get($id);if(!$c){http_response_code(404);exit('Contrat introuvable');}
try{$contractManager->assertPaymentEligible($id);}catch(Throwable $e){http_response_code(409);exit($e->getMessage());}
$_SESSION['contract_payment_csrf']=$_SESSION['contract_payment_csrf']??bin2hex(random_bytes(24));
$error='';$preview=null;$type=(string)($_POST['type_paiement']??'avancement');$progress=(float)($_POST['avancement']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!hash_equals((string)$_SESSION['contract_payment_csrf'],(string)($_POST['_csrf']??'')))throw new RuntimeException('Session expirée. Rechargez la page.');
  $q=$pdo->prepare('SELECT COUNT(*) FROM contrat_sous_traitance_paiement WHERE contrat_id=? AND fiche_id IS NULL');$q->execute([$id]);if((int)$q->fetchColumn()>0)throw new RuntimeException('Un dossier contractuel attend encore son PV signé et sa soumission en FEB.');
  if(!in_array($type,['acompte','avancement','solde'],true))throw new RuntimeException('Type de paiement invalide.');
  if($type==='acompte')$progress=0;elseif($type==='solde')$progress=100;
  $preview=$contractManager->paymentPreview($id,$type,$progress);
  if(isset($_POST['confirm'])){
   if((float)$preview['net']<=0)throw new RuntimeException('Aucun montant supplémentaire n’est exigible pour cette demande.');
   if(empty($_FILES['fne_document'])||(int)$_FILES['fne_document']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('La facture FNE est obligatoire.');
   if((int)$_FILES['fne_document']['size']>15*1024*1024)throw new RuntimeException('La facture FNE doit faire moins de 15 Mo.');
   $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['fne_document']['tmp_name']);$ext=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'][$mime]??null;if(!$ext)throw new RuntimeException('Facture FNE PDF, JPEG ou PNG attendue.');
   $name='fne_contrat_'.$id.'_'.date('YmdHis').'_'.bin2hex(random_bytes(4)).'.'.$ext;$target=$contractUploadDirectory.'/'.$name;if(!move_uploaded_file($_FILES['fne_document']['tmp_name'],$target))throw new RuntimeException('Téléversement de la facture FNE impossible.');@chmod($target,0664);$fne='uploads/contracts/'.$name;
   $pdo->beginTransaction();
   $q=$pdo->prepare("SELECT COUNT(*) FROM contrat_sous_traitance_paiement WHERE contrat_id=? AND fiche_id IS NULL");$q->execute([$id]);if((int)$q->fetchColumn()>0)throw new RuntimeException('Un dossier contractuel attend déjà son PV et sa soumission en FEB.');
   $q=$pdo->prepare("INSERT INTO contrat_sous_traitance_paiement(contrat_id,fiche_id,type_paiement,avancement_cumule,montant_brut,recuperation_acompte,retenue_garantie,restitution_retenue,montant_net,montant_decaisse_effectif,statut_financier,pv_path,facture_fne_path) VALUES(?,NULL,?,?,?,?,?,?,?,0,'soumis',NULL,?)");
   $q->execute([$id,$type,$progress,$preview['brut'],$preview['recuperation'],$preview['retenue'],$preview['restitution']??0,$preview['net'],$fne]);$paymentId=(int)$pdo->lastInsertId();$pdo->commit();
   header('Location: reception.php?paiement_id='.$paymentId);exit;
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
