<main class="mx-auto max-w-4xl px-4 py-8"><header class="rounded-3xl bg-black p-7 text-white"><p class="text-xs font-black uppercase tracking-[.22em] text-amber-300">Étape 1 · Dossier de paiement contractuel</p><h1 class="mt-2 text-2xl font-black"><?=$h($c['reference'].' · '.$c['fournisseur_nom'])?></h1><p class="mt-2 text-slate-300"><?=$h($c['chantier_code'].' · '.$c['chantier_titre'])?></p></header><?php if($error):?><div class="mt-4 rounded-2xl bg-rose-50 p-4 font-bold text-rose-800"><?=$h($error)?></div><?php endif;?><section class="mt-5 grid gap-3 md:grid-cols-3"><div class="rounded-2xl border bg-white p-4"><small class="font-black uppercase text-slate-500">1. Calcul et FNE</small><b class="mt-1 block text-amber-700">Étape actuelle</b></div><div class="rounded-2xl border bg-white p-4"><small class="font-black uppercase text-slate-500">2. PV interne</small><b class="mt-1 block">Constat et signatures</b></div><div class="rounded-2xl border bg-white p-4"><small class="font-black uppercase text-slate-500">3. FEB</small><b class="mt-1 block">Circuit normal de validation</b></div></section><form method="post" enctype="multipart/form-data" class="mt-5 rounded-3xl border bg-white p-6 shadow-sm"><input type="hidden" name="_csrf" value="<?=$h($_SESSION['contract_payment_csrf'])?>"><input type="hidden" name="contract_id" value="<?=$id?>"><div class="grid gap-4 md:grid-cols-2"><label class="font-bold">Nature du paiement<select name="type_paiement" id="type" class="mt-2 w-full rounded-2xl border p-3"><option value="acompte" <?=$type==='acompte'?'selected':''?>>Acompte pour exécution</option><option value="avancement" <?=$type==='avancement'?'selected':''?>>Paiement sur avancement</option><option value="solde" <?=$type==='solde'?'selected':''?>>Solde contractuel</option></select></label><label class="font-bold">Avancement cumulé constaté (%)<input type="number" name="avancement" min="0" max="100" step="0.01" value="<?=$h($progress)?>" class="mt-2 w-full rounded-2xl border p-3"></label></div><button class="mt-5 rounded-xl bg-black px-5 py-3 font-black text-white">Calculer le montant exigible</button><?php if($preview):?><div class="mt-6 grid gap-3 rounded-2xl bg-slate-50 p-5 sm:grid-cols-4"><?php foreach([['Brut',$preview['brut']],['Reprise acompte',$preview['recuperation']],['Retenue',$preview['retenue']],['Net proposé',$preview['net']]] as $item):?><div><small class="font-bold text-slate-500"><?=$item[0]?></small><b class="block text-lg"><?=number_format((float)$item[1],0,',',' ')?> F</b></div><?php endforeach;?></div><label class="mt-5 block font-black">Facture FNE obligatoire<input required type="file" name="fne_document" accept="application/pdf,image/jpeg,image/png" class="mt-2 w-full rounded-2xl border border-dashed border-amber-400 bg-amber-50 p-4"></label><p class="mt-3 rounded-2xl bg-blue-50 p-4 text-sm text-blue-900">Après validation, vous serez dirigé vers le PV interne. La FEB ne sera créée et transmise qu’après les deux signatures du PV.</p><button name="confirm" value="1" class="mt-5 rounded-xl bg-amber-500 px-5 py-3 font-black text-black">Créer le dossier et établir le PV</button><?php endif;?></form></main><script>const type=document.getElementById('type'),progress=document.querySelector('[name="avancement"]');function sync(){if(type.value==='acompte'){progress.value='0';progress.readOnly=true}else if(type.value==='solde'){progress.value='100';progress.readOnly=true}else progress.readOnly=false}type.addEventListener('change',sync);sync();</script><?php require __DIR__.'/../decaissement/includes/footer.php';?>
